         << any_of(v.begin(), v.end(), [](int x) { return x > 8; }) << ' '     // 1
         << none_of(v.begin(), v.end(), [](int x) { return x < 0; }) << '\n';  // 1

    // zliczanie
    cout << "count(5) = " << count(v.begin(), v.end(), 5) << '\n';             // 4
    cout << "parzystych = " << count_if(v.begin(), v.end(), [](int x) { return x % 2 == 0; }) << '\n';  // 3

    // wyszukiwanie pojedynczego elementu
    cout << "find(9): " << poz(find(v.begin(), v.end(), 9)) << '\n';           // 5
    cout << "find_if(>4): " << poz(find_if(v.begin(), v.end(), [](int x) { return x > 4; })) << '\n';      // 4
    cout << "find_if_not(<4): " << poz(find_if_not(v.begin(), v.end(), [](int x) { return x < 4; })) << '\n';  // 2
    vector<int> zbior = {9, 6};
    cout << "find_first_of({9,6}): " << poz(find_first_of(v.begin(), v.end(), zbior.begin(), zbior.end())) << '\n';  // 5
    cout << "adjacent_find: " << poz(adjacent_find(v.begin(), v.end())) << '\n';   // 8 (5, 5)

    // wyszukiwanie podciągów
    vector<int> wz = {1, 5}, piatki = {5, 5};
    cout << "search({1,5}): " << poz(search(v.begin(), v.end(), wz.begin(), wz.end())) << '\n';            // 3
    cout << "find_end({5,5}): " << poz(find_end(v.begin(), v.end(), piatki.begin(), piatki.end())) << '\n'; // 9
    cout << "search_n(3 x 5): " << poz(search_n(v.begin(), v.end(), 3, 5)) << '\n';                        // 8

    // porównywanie zakresów
    vector<int> w = {3, 1, 4, 1, 5, 8};
    auto [it1, it2] = mismatch(v.begin(), v.end(), w.begin(), w.end());
