    vector<int> a = {1, 2, 3}, b = {3, 1, 2};
    cout << "is_permutation: " << is_permutation(a.begin(), a.end(), b.begin(), b.end()) << '\n';   // 1

    // przejście po elementach
    for_each(v.begin(), v.begin() + 3, [](int x) { cout << x << ' '; });     // 3 1 4
    cout << '\n';
}

