#include <bits/stdc++.h>
using namespace std;

void wypisz(const string& nazwa, const vector<int>& v) {
    cout << nazwa << ':';
    for (int x : v) cout << ' ' << x;
    cout << '\n';
}

int main() {
    vector<int> a = {4, 7, 1, 8, 2, 8, 5};

    vector<int> b(a.size());
    copy(a.begin(), a.end(), b.begin());                      // cel ma już rozmiar
    vector<int> parz;
    copy_if(a.begin(), a.end(), back_inserter(parz), [](int x) { return x % 2 == 0; });
    wypisz("copy_if", parz);                                  // 4 8 2 8

    transform(b.begin(), b.end(), b.begin(), [](int x) { return x * 10; });
    wypisz("transform", b);                                   // 40 70 10 80 20 80 50

    replace(a.begin(), a.end(), 8, 0);
    wypisz("replace", a);                                     // 4 7 1 0 2 0 5

    a.erase(remove(a.begin(), a.end(), 0), a.end());
    wypisz("remove + erase", a);                              // 4 7 1 2 5

    reverse(a.begin(), a.end());
    wypisz("reverse", a);                                     // 5 2 1 7 4

    rotate(a.begin(), a.begin() + 2, a.end());
    wypisz("rotate", a);                                      // 1 7 4 5 2

    vector<int> c(5);
    generate(c.begin(), c.end(), [k = 1]() mutable { return k *= 2; });
    wypisz("generate", c);                                    // 2 4 8 16 32

    fill_n(c.begin(), 2, -1);
    wypisz("fill_n", c);                                      // -1 -1 8 16 32

    swap_ranges(a.begin(), a.begin() + 2, c.begin());
    wypisz("swap_ranges a", a);                               // -1 -1 4 5 2
    wypisz("swap_ranges c", c);                               // 1 7 8 16 32

    vector<int> d = {1, 1, 2, 2, 2, 3, 1};
    d.erase(unique(d.begin(), d.end()), d.end());
    wypisz("unique + erase", d);                              // 1 2 3 1

    vector<int> e = {1, 2, 3, 4, 5, 0};
    copy_backward(e.begin() + 1, e.begin() + 5, e.end());     // przesunięcie w prawo
    e[1] = 9;
    wypisz("copy_backward", e);                               // 1 9 2 3 4 5

    mt19937 rng(123);
    shuffle(d.begin(), d.end(), rng);                         // losowa kolejność
    vector<int> los;
    sample(b.begin(), b.end(), back_inserter(los), 3, rng);   // 3 różne pozycje z b
    cout << "sample: " << los.size() << " elementy\n";        // 3
}

