#include <bits/stdc++.h>
using namespace std;

int main() {
    // 1) kopiec maksymalny: budowa, dodawanie, zdejmowanie
    vector<int> h = {4, 1, 7, 3, 8, 5};
    make_heap(h.begin(), h.end());                       // O(n)
    cout << "max: " << h.front() << '\n';                // 8

    h.push_back(10);
    push_heap(h.begin(), h.end());                       // O(log n)
    cout << "max po dodaniu 10: " << h.front() << '\n';  // 10

    pop_heap(h.begin(), h.end());                        // 10 ląduje na końcu
    int top = h.back();
    h.pop_back();
    cout << "zdjęto " << top << ", nowe max: " << h.front() << '\n';   // zdjęto 10, nowe max: 8
    cout << "is_heap: " << is_heap(h.begin(), h.end()) << '\n';        // 1

    // 2) heapsort
    sort_heap(h.begin(), h.end());                       // rosnąco
    for (int x : h) cout << x << ' ';                    // 1 3 4 5 7 8
    cout << '\n';

    // 3) kopiec minimalny: łączenie dwóch najmniejszych (koszt jak w kodowaniu Huffmana)
    vector<long long> m = {5, 2, 4, 7};
    auto cmp = greater<long long>();
    make_heap(m.begin(), m.end(), cmp);
    long long koszt = 0;
    while (m.size() > 1) {
        pop_heap(m.begin(), m.end(), cmp);
        long long a = m.back(); m.pop_back();
        pop_heap(m.begin(), m.end(), cmp);
        long long b = m.back(); m.pop_back();
        koszt += a + b;
        m.push_back(a + b);
        push_heap(m.begin(), m.end(), cmp);
    }
    cout << "koszt: " << koszt << '\n';                  // 6 + 11 + 18 = 35
}

