#include <bits/stdc++.h>
using namespace std;

template <class T>
void wypisz(const string& nazwa, const vector<T>& v) {
    cout << nazwa << ':';
    for (auto x : v) cout << ' ' << x;
    cout << '\n';
}

int main() {
    vector<int> a = {3, 1, 4, 1, 5};
    vector<int> b = {2, 7, 1, 8, 2};
    int n = a.size();

    cout << "accumulate: " << accumulate(a.begin(), a.end(), 0LL) << '\n';                        // 14
    cout << "reduce: " << reduce(a.begin(), a.end(), 0LL) << '\n';                                // 14
    cout << "inner_product: " << inner_product(a.begin(), a.end(), b.begin(), 0LL) << '\n';       // 35
    cout << "transform_reduce: " << transform_reduce(a.begin(), a.end(), b.begin(), 0LL) << '\n'; // 35
    cout << "suma kwadratów: "
         << transform_reduce(a.begin(), a.end(), 0LL, plus<>(), [](int x) { return 1LL * x * x; }) << '\n';   // 52

    vector<long long> p(n);
    partial_sum(a.begin(), a.end(), p.begin());
    wypisz("partial_sum", p);                                        // 3 4 8 9 14
    inclusive_scan(a.begin(), a.end(), p.begin(), plus<>(), 0LL);   // init 0LL → liczy w long long
    wypisz("inclusive_scan", p);                                     // 3 4 8 9 14
    exclusive_scan(a.begin(), a.end(), p.begin(), 0LL);
    wypisz("exclusive_scan", p);                                     // 0 3 4 8 9

    vector<int> d(n);
    adjacent_difference(a.begin(), a.end(), d.begin());
    wypisz("adjacent_difference", d);                                // 3 -2 3 -3 4

    vector<int> id(n);
    iota(id.begin(), id.end(), 1);
    wypisz("iota", id);                                              // 1 2 3 4 5

    cout << "gcd(84, 36) = " << gcd(84, 36) << ", lcm(4, 6) = " << lcm(4, 6) << '\n';   // 12, 12
    cout << "midpoint(10, 15) = " << midpoint(10, 15) << '\n';       // 12 (zaokrąglenie w stronę 10)
}

