#include <bits/stdc++.h>
using namespace std;

struct Zawodnik {
    string nick;
    int punkty;
};

int main() {
    vector<int> v = {5, 3, 8, 1, 9, 2};

    ranges::sort(v);                                              // 1 2 3 5 8 9
    cout << "max: " << ranges::max(v) << '\n';                    // 9
    cout << "ile > 4: " << ranges::count_if(v, [](int x) { return x > 4; }) << '\n';   // 3
    cout << "lower_bound(4): " << *ranges::lower_bound(v, 4) << '\n';                  // 5
    cout << "binary_search(8): " << ranges::binary_search(v, 8) << '\n';               // 1

    // projekcje: sortowanie i szukanie po polu bez pisania lambdy
    vector<Zawodnik> z = {{"ala", 70}, {"bob", 95}, {"cyd", 80}};
    ranges::sort(z, ranges::greater{}, &Zawodnik::punkty);       // po punktach malejąco
    for (auto& [nick, p] : z) cout << nick << ' ' << p << '\n';  // bob 95, cyd 80, ala 70
    auto best = ranges::max_element(z, {}, &Zawodnik::punkty);
    cout << "najlepszy: " << best->nick << '\n';                  // bob
    auto it = ranges::find(z, string("cyd"), &Zawodnik::nick);
    cout << "cyd ma " << it->punkty << '\n';                      // 80

    // widoki: leniwe, bez kopiowania
    for (int i : views::iota(0, 3)) cout << i << ' ';             // 0 1 2
    cout << '\n';
    auto parz_kw = v | views::filter([](int x) { return x % 2 == 0; })
                     | views::transform([](int x) { return x * x; });
    for (int x : parz_kw) cout << x << ' ';                       // 4 64
    cout << '\n';
    for (int x : v | views::reverse | views::take(2)) cout << x << ' ';   // 9 8
    cout << '\n';
    for (int x : v | views::drop(4)) cout << x << ' ';            // 8 9
    cout << '\n';

    vector<int> w(parz_kw.begin(), parz_kw.end());               // materializacja widoku (C++20)
    cout << "w.size() = " << w.size() << '\n';                    // 2

    // usuwanie duplikatów: ranges::unique zwraca subrange
    vector<int> d = {3, 1, 3, 2, 1};
    ranges::sort(d);
    auto [b, e] = ranges::unique(d);
    d.erase(b, e);
    cout << "unikalne: " << d.size() << '\n';                     // 3
}

