int main() {
    vector<int> a = {1, 3, 3, 5, 8};

    // wyszukiwanie binarne (zakres posortowany!)
    auto lb = lower_bound(a.begin(), a.end(), 3);              // pierwszy >= 3
    auto ub = upper_bound(a.begin(), a.end(), 3);              // pierwszy > 3
    cout << lb - a.begin() << ' ' << ub - a.begin() << '\n';   // 1 3
    auto [l, r] = equal_range(a.begin(), a.end(), 3);
    cout << "trójek: " << r - l << '\n';                       // 2
    cout << binary_search(a.begin(), a.end(), 4) << '\n';      // 0
    cout << "elementów w [2, 6]: "
         << upper_bound(a.begin(), a.end(), 6) - lower_bound(a.begin(), a.end(), 2) << '\n';   // 3

    // min / max
    cout << min(4, 7) << ' ' << max({4, 9, 2}) << '\n';        // 4 9
    auto [mn, mx] = minmax({5, 1, 9});
    cout << mn << ' ' << mx << '\n';                           // 1 9
    cout << clamp(15, 0, 10) << ' ' << clamp(-3, 0, 10) << '\n';   // 10 0

    vector<int> v = {4, 1, 7, 1, 7};
    cout << min_element(v.begin(), v.end()) - v.begin() << ' '      // 1 (pierwsze minimum)
         << max_element(v.begin(), v.end()) - v.begin() << '\n';    // 2 (pierwsze maksimum)
    auto [itMin, itMax] = minmax_element(v.begin(), v.end());
    cout << itMin - v.begin() << ' ' << itMax - v.begin() << '\n';  // 1 4 (ostatnie maksimum!)

    // porównanie leksykograficzne
    vector<int> p = {1, 2, 3}, q = {1, 2, 5};
    cout << lexicographical_compare(p.begin(), p.end(), q.begin(), q.end()) << '\n';   // 1
    cout << (p < q) << '\n';                                   // 1 — to samo dla całych kontenerów
}

